        TeaToken(TARGET).setTaxFeePercent(48);
        TeaToken(TARGET).setLiquidityFeePercent(48);

        vm.stopPrank();

        // Give some tokens to a victim address to trigger transfers
        victim1 = address(0x111);
        victim2 = address(0x222);

        // Get some initial tokens to victim1 by transferring from owner
        vm.prank(owner);
        // Transfer a reasonable amount - 1000 tokens with 2 decimals = 100000
        TeaToken(TARGET).transfer(victim1, 100000); // 1000 tokens
    }

